result:
.xt_card {
  position: relative;
}

.btn_box {
  display: flex;
  justify-content: flex-end;
  font-size: 14px;
  margin-bottom: 10px;

  span {
    margin-right: 10px;
    display: inline-block;
    vertical-align: bottom;
    height: 22px;
  }
}

.form_body {
  margin-bottom: 12px;

  &:first-child {
    border-bottom: 1px dashed #91D5FF;
  }
}

.form_box {
  display: flex;
  flex-direction: row;

  .form_tags {
    width: 120px;
    min-width: 120px;
    max-width: 120px;
    flex: 0 0 120px;
    text-align: right;

    span {
      display: inline-block;
      background: #91D5FF;
      color: #fff;
      font-size: 12px;
      padding: 4px 12px;
      border-radius: 4px;
    }
  }

  .form_item {
    flex: auto;
    overflow-x: hidden;
    padding-left: 15px;

    .form_item_box {
      display: flex;
      flex-direction: row;
      margin-bottom: 25px;
    }

    .form_label {
      // line-height: 40px;
      font-size: 14px;
      white-space: nowrap;
      position: relative;

      .label_text {
        position: relative;
        z-index: 10;
      }

      .label_tag {
        position: absolute;
        background: #67C23A;
        color: #fff;
        font-size: 8px;
        width: 12px;
        height: 12px;
        line-height: 12px;
        text-align: center;
        font-style: normal;
        border-radius: 50%;
        display: inline-block;
        padding: 2px;
        right: -10px;
        top: 6px;
      }
    }

    .form_content {
      // line-height: 40px;
      font-size: 14px;
      color: #909399;
      padding-left: 10px;
      flex: auto;
      padding-right: 10px;
      overflow: hidden

    }

    .form_content_p {
      // line-height: 40px;
      font-size: 14px;
      color: #909399;
      padding-left: 10px;
      // flex: auto;
      padding-right: 10px;
      overflow: hidden;
      padding-right: 5px;

      sup {
        font-size: 10px;
        font-weight: 400;
        background: #F0F6FE;
        top: -10px;
        right: 0;
      }
    }
  }
}

.submit_btn {
  text-align: center
}

.d_edit {
  position: absolute;
  right: 12px;
  z-index: 1;
}

// 必填样式
.isRequiredRed::before {
  content: '*';
  color: #F56C6C;
  margin-right: 4px;
  position: absolute;
  left: -10px;
  top: 2px;
}
// 必填样式
.isRequiredBlack::before {
  content: '*';
  color: #333333;
  margin-right: 4px;
  position: absolute;
  left: -10px;
  top: 2px;
}

.dev_tabs {
  /deep/ .el-tabs__item {
    font-size: 14px;
    font-weight: normal;
    color: #000000;
  }

  /deep/ .el-tabs__item.is-active {
    color: #0D8EFF;
    font-size: 15px;
    font-weight: bold;
  }
}
